    # Maintain original unchanged grids where no diagonal motif is evident.
    if len(colors) < 2:
        return [row[:] for row in grid]
    order = [colors.get(i, 0) for i in range(4)]
    return [[order[(c-r) % 4] for c in range(w)] for r in range(h)]


